import{_ as p,a0 as d,w as o,s as r,ao as l,I as n,x as s,a1 as t,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"将 i3 与多个显示器配合使用 | LCTT x X-CMD","titleTemplate":false,"description":"将 i3 与多个显示器配合使用 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将 i3 与多个显示器配合使用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将 i3 与多个显示器配合使用 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190624 Using i3 with multiple monitors","title":"将 i3 与多个显示器配合使用","tag":"201906","desc":""},"relativePath":"201906/20190624 Using i3 with multiple monitors.md","filePath":"[post].md"}'),h={name:"201906/20190624 Using i3 with multiple monitors.md"};function g(k,i,u,b,c,f){const a=d("Link");return o(),r("div",null,[i[18]||(i[18]=l('<h1 id="将-i3-与多个显示器配合使用" tabindex="-1">将 i3 与多个显示器配合使用 <a class="header-anchor" href="#将-i3-与多个显示器配合使用" aria-label="Permalink to “将 i3 与多个显示器配合使用”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/i3-title-816x345.jpg" alt=""></p><p>你在 Linux 工作站上使用多个显示器吗？一次看到很多东西可能是有益的。但在我们的工作中通常有比实际显示器更多的窗口 —— 这是一件好事，因为一次看到太多东西可能会分散注意力。因此能够切换我们在单个显示器上看到的内容似乎很重要。</p><p>让我们来看看 i3，它是一个流行的平铺窗口管理器，可以与多个显示器配合使用。并且有许多其他窗口管理器没有的便利功能，它能够独立地在各个显示器上切换工作区。</p><h3 id="快速介绍-i3" tabindex="-1">快速介绍 i3 <a class="header-anchor" href="#快速介绍-i3" aria-label="Permalink to “快速介绍 i3”">​</a></h3>',5)),n("p",null,[i[1]||(i[1]=s("大约三年前，",-1)),t(a,{href:"https://fedoramagazine.org/getting-started-i3-window-manager/"},{default:e(()=>[...i[0]||(i[0]=[s("Fedora Magazine 已经写了一篇关于 i3 的文章",-1)])]),_:1}),i[2]||(i[2]=s("。这是有史以来最受欢迎的文章之一！虽然情况并非总是如此，但 i3 非常稳定，而且那篇文章如今也很准确。所以，这次不会重复太多内容，本篇只涵盖了让 i3 启动和运行的极少内容，如果你是 i3 的新手，想要了解更多基础知识的话，欢迎你继续阅读。",-1))]),i[19]||(i[19]=l(`<p>要在系统上安装 i3，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install i3</span></span></code></pre></div><p>完成后，注销，然后在登录屏幕上选择 i3 作为窗口管理器，然后重新登录。</p><p>当你第一次运行 i3 时，系统会询问你是否要继续进行自动配置 —— 在此处回答是。之后，你将被要求选择 “mod 键”。如果你不确定，只需接受默认值，即将 Windows/Super 键设置为 mod 键。你将主要使用此键用于窗口管理器中的快捷方式。</p><p>此时，你应该在底部看到一个小条和一个空白屏幕。我们来看看一些基本的快捷方式。</p><p>打开终端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + enter</span></span></code></pre></div><p>切换到第二个工作区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + 2</span></span></code></pre></div><p>通过以下两个步骤打开 firefox，首先：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + d</span></span></code></pre></div><p>然后输入 “firefox” 并按回车键。</p><p>将其移动到第一个工作区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + 1</span></span></code></pre></div><p>切换到第一个工作区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + 1</span></span></code></pre></div><p>此时，你将并排看到一个终端和一个 firefox 窗口。要关闭窗口，请按：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + q</span></span></code></pre></div><p>还有更多的快捷方式，但这些足够让你开始使用 i3。</p><p>要退出 i3（并退出登录）按：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + e</span></span></code></pre></div><p>然后在右上角使用鼠标确认。</p><h3 id="同时让多个屏幕工作" tabindex="-1">同时让多个屏幕工作 <a class="header-anchor" href="#同时让多个屏幕工作" aria-label="Permalink to “同时让多个屏幕工作”">​</a></h3><p>现在我们已经启动并运行了 i3，让我们把所有这些屏幕都用到！</p><p>为此，我们需要使用命令行，因为 i3 非常轻量级，并且没有 GUI 来管理其他屏幕。如果这听起来很难也不用担心，它实际上非常简单！</p><p>我们将使用的命令称为 <code>xrandr</code>。如果你的系统上没有 <code>xrandr</code>，请运行以下命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install xrandr</span></span></code></pre></div><p>当它安装完毕后，让我们继续运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xrandr</span></span></code></pre></div><p>输出列出了所有可用输出设备，并通过显示支持的分辨率指示哪些输出连接了屏幕（通过电缆连接的显示器）。好消息是，我们不需要关心使它们工作的分辨率。</p><p>这个例子显示了笔记本电脑的主屏幕（名为 eDP1），以及连接到 HDMI-2 输出的第二个显示器，它位于笔记本电脑的右侧。要打开它，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xrandr --output HDMI-2 --auto --right-of eDP1</span></span></code></pre></div><p>就是这样！你的屏幕现已激活。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/0-1-1024x384.png" alt="第二个屏幕激活。截屏上显示命令与文章中略有不同，它设置了更小的分辨率以使截屏适合阅读"></p><h3 id="在多个屏幕上管理工作区" tabindex="-1">在多个屏幕上管理工作区 <a class="header-anchor" href="#在多个屏幕上管理工作区" aria-label="Permalink to “在多个屏幕上管理工作区”">​</a></h3><p>在多个屏幕上切换工作区和创建新工作区非常类似于只有一个屏幕的情况。新工作区会在当前处于活动状态（鼠标光标所在位置）的屏幕上创建。</p><p>因此，要切换到特定工作区（或在不存在的情况下创建新工作区），请按：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + NUMBER</span></span></code></pre></div><p>你可以独立切换各个显示器上的工作区！</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/1-1-1024x384.png" alt="工作空间 2 在左侧屏幕，工作空间 4 在右侧屏幕"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/1-2-1024x384.png" alt="左侧屏幕切换为工作空间 3，右侧屏幕仍为工作空间 4"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/1-3-1024x384.png" alt="右侧屏幕切换为工作空间 5，左侧屏幕仍为空间空间 3"></p><h3 id="在显示器之间移动工作区" tabindex="-1">在显示器之间移动工作区 <a class="header-anchor" href="#在显示器之间移动工作区" aria-label="Permalink to “在显示器之间移动工作区”">​</a></h3><p>我们可以通过以下命令将窗口移动到不同的工作区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + NUMBER</span></span></code></pre></div><p>我们也可以将工作区移动到不同的屏幕。但是，此操作没有默认快捷方式，因此我们必须先创建它。</p><p>要创建自定义快捷方式，你需要在你选择的文本编辑器中打开配置文件（本文使用 <code>vim</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim ~/.config/i3/config</span></span></code></pre></div><p>并将以下行添加到配置文件的最底部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Moving workspaces between screens</span></span>
<span class="line"><span>bindsym $mod+p move workspace to output right</span></span></code></pre></div><p>保存、关闭并重新加载以使配置生效，按下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + r</span></span></code></pre></div><p>现在你可以将活跃的工作区移动到第二个显示器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + p</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/2-1-1024x384.png" alt="打开火狐浏览器的工作空间 2 在左侧"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/2-2-1024x384.png" alt="打开火狐浏览器的工作空间 2 移动到第二个屏幕"></p><p>就是这些了！享受你的新多显示器体验，并了解更多 i3，欢迎阅读 Fedora Magazine 上之前关于 i3 的文章，或者查看官方 i3 文档。</p><hr>`,58)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),t(a,{href:"https://fedoramagazine.org/using-i3-with-multiple-monitors/"},{default:e(()=>[...i[3]||(i[3]=[s("https://fedoramagazine.org/using-i3-with-multiple-monitors/",-1)])]),_:1})]),n("p",null,[i[9]||(i[9]=s("作者：",-1)),t(a,{href:"https://fedoramagazine.org/author/asamalik/"},{default:e(()=>[...i[5]||(i[5]=[s("Adam Šamalík",-1)])]),_:1}),i[10]||(i[10]=s(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[6]||(i[6]=[s("lujun9972",-1)])]),_:1}),i[11]||(i[11]=s(" 译者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:e(()=>[...i[7]||(i[7]=[s("geekpi",-1)])]),_:1}),i[12]||(i[12]=s(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...i[8]||(i[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[13]||(i[13]=[s("LCTT",-1)])]),_:1}),i[16]||(i[16]=s(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...i[14]||(i[14]=[s("Linux中国",-1)])]),_:1}),i[17]||(i[17]=s(" 荣誉推出",-1))])])}const x=p(h,[["render",g]]);export{C as __pageData,x as default};
